const listActivities = `-- name: ListActivities :many
SELECT a.activity_pk, a."partition", a.account_id, a.region, a.activity_id, a.group_partition, a.group_account_id, a.group_region, a.group_name, a.group_id, a.kind, a.instance_id, a.subnet_id, a.origin_event_id, a.retry_at, a.instance_warmup, a.has_launch_tags, a.protected_from_scale_in, a.data_activity_id, a.data_auto_scaling_group_arn, a.data_auto_scaling_group_name, a.data_auto_scaling_group_state, a.data_cause, a.data_description, a.data_details, a.data_end_time, a.data_progress, a.data_start_time, a.data_status_code, a.data_status_message, a.launch_template_launch_template_id, a.launch_template_launch_template_name, a.launch_template_version, a.warm_pool_state FROM asg_activities a WHERE a.partition = ?1 AND a.account_id = ?2 AND a.region = ?3 AND (CAST(?4 AS TEXT) = '' OR a.group_name = ?4) AND (?5 != 0 OR EXISTS (SELECT 1 FROM asg_groups g WHERE g.partition = a.group_partition AND g.account_id = a.group_account_id AND g.region = a.group_region AND g.name = a.group_name AND g.native_id = a.group_id)) ORDER BY a.data_start_time DESC, a.activity_id
`

type ListActivitiesParams struct {
	Partition      string
	AccountID      string
	Region         string
	GroupName      string
	IncludeDeleted interface{}
}

func (q *Queries) ListActivities(ctx context.Context, arg ListActivitiesParams) ([]AsgActivity, error) {
	rows, err := q.db.QueryContext(ctx, listActivities,
		arg.Partition,
		arg.AccountID,
		arg.Region,
		arg.GroupName,
		arg.IncludeDeleted,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AsgActivity{}
	for rows.Next() {
		var i AsgActivity
		if err := rows.Scan(
			&i.ActivityPk,
			&i.Partition,
			&i.AccountID,
			&i.Region,
			&i.ActivityID,
			&i.GroupPartition,
			&i.GroupAccountID,
			&i.GroupRegion,
			&i.GroupName,
			&i.GroupID,
			&i.Kind,
			&i.InstanceID,
			&i.SubnetID,
			&i.OriginEventID,
			&i.RetryAt,
			&i.InstanceWarmup,
			&i.HasLaunchTags,
			&i.ProtectedFromScaleIn,
			&i.DataActivityID,
			&i.DataAutoScalingGroupArn,
			&i.DataAutoScalingGroupName,
			&i.DataAutoScalingGroupState,
			&i.DataCause,
			&i.DataDescription,
			&i.DataDetails,
			&i.DataEndTime,
			&i.DataProgress,
			&i.DataStartTime,
			&i.DataStatusCode,
			&i.DataStatusMessage,
			&i.LaunchTemplateLaunchTemplateID,
			&i.LaunchTemplateLaunchTemplateName,
			&i.LaunchTemplateVersion,
			&i.WarmPoolState,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

